test('initializes with provided values', () => {
  const { result } = renderHook(() =>
    useFormSchema({ name: () => null }, { name: 'Alice' })
  );
  expect(result.current.values.name).toBe('Alice');
});

test('handleChange updates field value', () => {
  const { result } = renderHook(() =>
    useFormSchema({ name: () => null }, { name: '' })
  );
  act(() => result.current.handleChange('name', 'Bob'));
  expect(result.current.values.name).toBe('Bob');
});

test('validate populates errors for invalid fields', () => {
  const { result } = renderHook(() =>
    useFormSchema(
      { age: (v) => Number(v) >= 18 ? null : 'Too young' },
      { age: 16 }
    )
  );
  act(() => result.current.validate());
  expect(result.current.errors.age).toBe('Too young');
});

test('isValid is false when errors exist', () => {
  const { result } = renderHook(() =>
    useFormSchema(
      { email: (v) => String(v).includes('@') ? null : 'Bad email' },
      { email: 'notanemail' }
    )
  );
  act(() => result.current.validate());
  expect(result.current.isValid).toBe(false);
});

test('isValid is true when all fields pass', () => {
  const { result } = renderHook(() =>
    useFormSchema(
      { x: () => null, y: () => null },
      { x: 1, y: 2 }
    )
  );
  act(() => result.current.validate());
  expect(result.current.isValid).toBe(true);
});

// __hidden__
test('errors cleared for fields that become valid', () => {
  const { result } = renderHook(() =>
    useFormSchema(
      { code: (v) => String(v).length === 4 ? null : 'Must be 4 chars' },
      { code: 'ab' }
    )
  );
  act(() => result.current.validate());
  expect(result.current.errors.code).toBe('Must be 4 chars');
  act(() => result.current.handleChange('code', 'abcd'));
  act(() => result.current.validate());
  expect(result.current.errors.code).toBeNull();
});

solution:
import { useState, useCallback } from 'react';

export function useFormSchema<T extends Record<string, unknown>>(
  schema: Record<keyof T, (v: unknown) => string | null>,
  initial: T
) {
  const [values, setValues] = useState<T>(initial);
  const [errors, setErrors] = useState<Record<keyof T, string | null>>(
    () => Object.fromEntries(Object.keys(schema).map(k => [k, null])) as any
  );

  const handleChange = useCallback((field: keyof T, value: unknown) => {
    setValues(prev => ({ ...prev, [field]: value }));
  }, []);

  const validate = useCallback(() => {
    const newErrors = {} as Record<keyof T, string | null>;
    for (const key of Object.keys(schema) as (keyof T)[]) {
      newErrors[key] = schema[key](values[key]);
    }
    setErrors(newErrors);
  }, [schema, values]);

  const isValid = Object.values(errors).every(e => e === null);

  return { values, errors, handleChange, validate, isValid };
}
